const input = $json.body ?? $json;
const source = input.post_close ?? input;
const identity = { candidate_key: source.candidate_key ?? null, normalized_identity_key: source.normalized_identity_key ?? null, lead_id: source.leadId ?? source.lead_id ?? null, deal_id: source.dealId ?? source.deal_id ?? null, property_id: source.propertyId ?? source.property_id ?? null, parcel_id: source.parcel_id ?? null };
const strategy = String(source.exit_strategy ?? source.disposition_strategy ?? '').toLowerCase().trim();
const allowedStrategies = ['assignment','novation','double_close','wholetail','resale','hold','review'];
const status = String(source.post_close_status ?? source.status ?? 'post_close_pending').toLowerCase().trim();
const allowedStatuses = ['post_close_pending','buyer_completed','seller_completed','assignment_fee_pending','proceeds_pending','profit_recorded','loss_recorded','reconciled','closed_out','failed','cancelled'];
const prior = String(source.prior_post_close_status ?? '').toLowerCase().trim();
const transitionMap = { post_close_pending:['buyer_completed','seller_completed','assignment_fee_pending','proceeds_pending','failed','cancelled'], buyer_completed:['seller_completed','assignment_fee_pending','proceeds_pending','profit_recorded','loss_recorded'], seller_completed:['buyer_completed','assignment_fee_pending','proceeds_pending','profit_recorded','loss_recorded'], assignment_fee_pending:['proceeds_pending','profit_recorded','loss_recorded','failed'], proceeds_pending:['profit_recorded','loss_recorded','failed'], profit_recorded:['reconciled','closed_out'], loss_recorded:['reconciled','closed_out'], reconciled:['closed_out'], closed_out:[], failed:['post_close_pending','cancelled'], cancelled:[] };
const validStrategy = allowedStrategies.includes(strategy);
const validStatus = allowedStatuses.includes(status);
const missing=[];
if (!identity.candidate_key && !identity.normalized_identity_key && !identity.property_id && !identity.parcel_id) missing.push('property_identity');
if (!source.executed_contract_id && !source.contract_id) missing.push('executed_contract_id');
if (!validStrategy) missing.push('supported_exit_strategy');
if (!validStatus) missing.push('supported_post_close_status');
const transitionValid = !prior || prior === status || (transitionMap[prior] ?? []).includes(status);
const amount = (v) => { const n=Number(v); return Number.isFinite(n) ? n : null; };
const contractPrice=amount(source.contract_price ?? source.purchase_price);
const buyerPrice=amount(source.buyer_purchase_price ?? source.buyer_price);
const assignmentFee=amount(source.assignment_fee);
const closingCosts=amount(source.closing_costs);
const holdingCosts=amount(source.holding_costs);
const otherCosts=amount(source.other_costs);
let grossProfit=null;
if (strategy === 'assignment' && assignmentFee !== null) grossProfit=assignmentFee;
else if (contractPrice !== null && buyerPrice !== null) grossProfit=buyerPrice-contractPrice-(closingCosts ?? 0)-(holdingCosts ?? 0)-(otherCosts ?? 0);
const profitRecorded=amount(source.realized_profit ?? source.net_profit) ?? grossProfit;
const reconciliationRequired = ['profit_recorded','loss_recorded','reconciled','closed_out'].includes(status);
if (reconciliationRequired && profitRecorded === null) missing.push('realized_profit');
const readiness = missing.length ? 'needs_data' : !transitionValid ? 'invalid_transition' : status === 'closed_out' ? 'closed_out' : status === 'reconciled' ? 'reconciled' : ['profit_recorded','loss_recorded'].includes(status) ? 'profit_outcome_recorded' : 'in_progress';
const outcome = profitRecorded === null ? 'pending' : profitRecorded > 0 ? 'profit' : profitRecorded < 0 ? 'loss' : 'break_even';
const nextAction = readiness === 'needs_data' ? 'Collect the missing post-close or financial reconciliation data.' : readiness === 'invalid_transition' ? 'Review the prior post-close state and use a supported transition.' : status === 'closed_out' ? 'Archive the completed transaction and include it in performance reporting.' : status === 'reconciled' ? 'Complete close-out and performance reporting.' : reconciliationRequired ? 'Reconcile the realized proceeds and costs before final close-out.' : status === 'assignment_fee_pending' || status === 'proceeds_pending' ? 'Confirm authorized receipt/proceeds information before recording the final outcome.' : 'Confirm buyer/seller completion milestones and advance the post-close state.';
const packageData={identity,exit_strategy:strategy,executed_contract_id:source.executed_contract_id ?? source.contract_id ?? null,selected_buyer:source.selected_buyer ?? null,closing_date:source.closing_date ?? null,post_close_status:status,prior_post_close_status:prior || null,financials:{contract_price:contractPrice,buyer_purchase_price:buyerPrice,assignment_fee:assignmentFee,closing_costs:closingCosts,holding_costs:holdingCosts,other_costs:otherCosts,gross_or_realized_profit:profitRecorded},outcome};
return [{json:{ok:!['needs_data','invalid_transition'].includes(readiness),readiness,post_close_status:status,exit_strategy:strategy,identity,financials:packageData.financials,outcome,transaction_package:packageData,profit_tracking:{calculated_profit:grossProfit,realized_profit:profitRecorded,profit_outcome:outcome},missing_requirements:missing,transition_valid:transitionValid,next_action:nextAction,policy:{no_financial_verification_claim:true,no_tax_advice:true,no_legal_validation:true,no_closing_execution:true,recordkeeping_and_reconciliation_only:true}}}];

const input=$input.first().json;
try {
  const base=$env.INSULA_CRM_BASE_URL, apiKey=$env.INSULA_CRM_API_KEY;
  const leadId=Number(input.insulaLeadId||input.leadId||input.lead_id||input.property_identity?.lead_id||input.identity?.lead_id||input.transaction_ids?.lead_id||input.crm_update?.lead_id||0);
  if(base&&apiKey&&leadId){
    const payload=input.post_close_profit||input.buyer_matching||input.buyer_disposition||input.exit_strategy_gate||input;
    await this.helpers.httpRequest({
      method:'POST',url:base+'/api/v1/activities',
      headers:{'X-API-Key':apiKey,'Content-Type':'application/json',
        'Idempotency-Key':'acquisition:post-close-profit:'+leadId+':'+String(input.candidate_key||input.normalized_identity_key||input.external_id||input.dealId||input.deal_id||'record')+':v1'},
      body:{lead_id:leadId,type:'stage_change',
        subject:"Post-close profit tracking updated",
        body:'Workflow event: post-close-profit. Status/readiness: '+String(payload.status||payload.readiness||payload.current_status||payload.closeout_status||payload.post_close_status||payload.transaction_status||'updated')+'. Next action: '+String(payload.next_action||input.next_action||'review').slice(0,500)},
      json:true
    });
  }
}catch(error){ console.log('InsulaCRM activity sync failed:',error.message); }
return [{json:input}];
